import { describe, expect, it } from 'vitest';
import { server } from '../../test/msw.ts';
import { TEST_ACCESS_KEY, weatherstack } from '../../test/weatherstack.ts';
import { createWeatherstackClient, type WeatherLookup } from './client.ts';

const client = (timeoutMs?: number) =>
  createWeatherstackClient({
    baseUrl: 'http://weatherstack.test',
    accessKey: TEST_ACCESS_KEY,
    ...(timeoutMs === undefined ? {} : { timeoutMs }),
  });

const failure = (lookup: WeatherLookup) => {
  if (lookup.ok) throw new Error('expected a failed lookup');
  return lookup;
};

describe('Weatherstack client', () => {
  it('S5.2 sends one /current request with query, units=f and the access key', async () => {
    const requests: URL[] = [];
    server.use(weatherstack.ok(requests));

    await client().current('85268, AZ, USA');

    expect(requests).toHaveLength(1);
    expect(Object.fromEntries(requests[0]!.searchParams)).toEqual({
      access_key: TEST_ACCESS_KEY,
      query: '85268, AZ, USA',
      units: 'f',
    });
  });

  it('S5.5 parses string lat/lon into numbers on success', async () => {
    server.use(weatherstack.ok());

    const lookup = await client().current('85268, AZ, USA');

    expect(lookup.ok).toBe(true);
    if (!lookup.ok) return;
    expect(lookup.response.location).toMatchObject({ lat: 33.609, lon: -111.729 });
    expect(lookup.response.current.temperature).toBe(79);
  });

  it.each([
    ['NETWORK', weatherstack.networkError()],
    ['HTTP_ERROR', weatherstack.httpError(500)],
    ['UPSTREAM_ERROR', weatherstack.successFalse()],
    ['INVALID_RESPONSE', weatherstack.notJson()],
    ['INVALID_RESPONSE', weatherstack.missingCurrent()],
    ['INVALID_RESPONSE', weatherstack.withLocation({ lat: 'north' })],
    ['INVALID_RESPONSE', weatherstack.withLocation({ lat: '91' })],
    ['INVALID_RESPONSE', weatherstack.withLocation({ lon: '-181' })],
  ])('S5.5 reports %s for each failure mode', async (reason, handler) => {
    server.use(handler);

    const lookup = failure(await client().current('85268, AZ, USA'));

    expect(lookup.reason).toBe(reason);
    expect(lookup.detail).not.toContain(TEST_ACCESS_KEY);
  });

  it('S5.5 reports TIMEOUT when no response arrives in time', async () => {
    server.use(weatherstack.timeout());

    const lookup = failure(await client(50).current('85268, AZ, USA'));

    expect(lookup.reason).toBe('TIMEOUT');
  });

  it('S5.2 redacts the access key from failure details', async () => {
    // An invalid base URL makes fetch throw with the full URL, key included, in its message.
    const broken = createWeatherstackClient({ baseUrl: 'http://[bad', accessKey: TEST_ACCESS_KEY });

    const lookup = await broken.current('85268, AZ, USA').catch((error: unknown) => error);

    // `new URL` rejects the base before any request; the client must not leak the key either way.
    expect(JSON.stringify(lookup, Object.getOwnPropertyNames(lookup ?? {}))).not.toContain(
      TEST_ACCESS_KEY,
    );
  });
});
