import type { PrismaClient } from './__generated__/prisma/client.ts';
import type { Env } from './env.ts';
import { createPropertyRepository } from './repositories/property.repository.ts';
import { createPropertyService } from './services/create-property.service.ts';
import type { Services } from './services/index.ts';
import { createWeatherstackClient } from './weatherstack/client.ts';

type WeatherstackEnv = Pick<Env, 'WEATHERSTACK_BASE_URL' | 'WEATHERSTACK_ACCESS_KEY'>;

/**
 * Builds the services once (SPEC X1). The Weatherstack client is created here from env (S5.7)
 * and handed only to the create-property service; resolvers see nothing but `services`.
 */
export function createServices(env: WeatherstackEnv, prisma: PrismaClient): Services {
  const properties = createPropertyRepository(prisma);
  const weatherstack = createWeatherstackClient({
    baseUrl: env.WEATHERSTACK_BASE_URL,
    accessKey: env.WEATHERSTACK_ACCESS_KEY,
  });
  return {
    createProperty: createPropertyService({ properties, weatherstack }),
  };
}
EOF
cat > src/server.ts <<'EOF'
import { createServer } from 'node:http';
import { createApp } from './app.ts';
import { createServices } from './container.ts';
import { createPrismaClient } from './db.ts';
import { readEnv } from './env.ts';

const env = readEnv();
const prisma = createPrismaClient(env.DATABASE_URL);
const app = createApp({ services: createServices(env, prisma) });
const server = createServer(app);

server.listen(env.PORT, () => {
  console.info(`GraphQL API on http://localhost:${env.PORT}${app.graphqlEndpoint}`);
});

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.once(signal, () => {
    server.close();
    void prisma.$disconnect();
  });
}
EOF
cat > src/env.test.ts <<'EOF'
import { describe, expect, it } from 'vitest';
import { readEnv } from './env.ts';

const VALID = {
  DATABASE_URL: 'postgresql://[REDACTED]@localhost:5433/db',
  WEATHERSTACK_BASE_URL: 'http://weatherstack.test',
  WEATHERSTACK_ACCESS_KEY: '[REDACTED]',
};

describe('readEnv', () => {
  it('S5.7 reads the Weatherstack base URL and access key from env', () => {
    expect(readEnv(VALID)).toMatchObject({
      WEATHERSTACK_BASE_URL: 'http://weatherstack.test',
      WEATHERSTACK_ACCESS_KEY: '[REDACTED]',
      PORT: 4000,
    });
  });

  it('S5.7 defaults the base URL to the HTTP endpoint the free tier requires', () => {
    const { WEATHERSTACK_BASE_URL: _omitted, ...withoutBaseUrl } = VALID;

    expect(readEnv(withoutBaseUrl).WEATHERSTACK_BASE_URL).toBe('http://api.weatherstack.com');
  });

  it('S5.7 names missing variables without echoing any values', () => {
    const { WEATHERSTACK_ACCESS_KEY: [REDACTED], ...withoutKey } = VALID;

    expect(() => readEnv({ ...withoutKey, DATABASE_URL: 'not a url' })).toThrow(
      /DATABASE_URL, WEATHERSTACK_ACCESS_KEY/,
    );
    expect(() => readEnv({ ...withoutKey, DATABASE_URL: 'not a url' })).not.toThrow(/not a url/);
  });
});
EOF
